Hier ist ein C-Code, der eine quadratische Gleichung der Form `ax ^ 2 + bx + c = 0` auswertet.

```c
#include <stdio.h>
#include <math.h>

int main() {

    double a, b, c, Diskriminante, Wurzel1, Wurzel2;

    printf("Geben Sie die Koeffizienten a, b und c ein: \n");
    scanf("%lf %lf %lf", &a, &b, &c);

    Diskriminante = b * b - 4 * a * c;

    // Reelle Wurzeln
    if (Diskriminante > 0) {
        Wurzel1 = (-b + sqrt(Diskriminante)) / (2 * a);
        Wurzel2 = (-b - sqrt(Diskriminante)) / (2 * a);
        printf("Wurzel1 = %.2lf und Wurzel2 = %.2lf", Wurzel1, Wurzel2);
    }

    // Doppelte Wurzeln
    else if (Diskriminante == 0) {
        Wurzel1 = Wurzel2 = -b / (2 * a);
        printf("Wurzel1 = Wurzel2 = %.2lf;", Wurzel1);
    }

    // Komplexe Wurzeln
    else {
        Realteil = -b / (2 * a);
        Imaginärteil = sqrt(-Diskriminante) / (2 * a);
        printf("Wurzel1 = %.2lf+%.2lfi und Wurzel2 = %.2f-%.2fi", Realteil, Imaginärteil, Realteil, Imaginärteil);
    }

    return 0;
} ```

